package app.silkquest.companion; import android.content.Context;import org.json.*;import java.util.*;final class PhoneClient {static boolean isPaired=true;static Response response;static Runnable during;static final Pref p=new Pref();static boolean paired(Context c){return isPaired;}static String statusText(Context c){return p.getString("status","");}static void selectLocalNetwork(Context c){}static Pref prefs(Context c){return p;}interface ConnectionHook{}static class Response{int code;JSONObject json;Response(int n,JSONObject j){code=n;json=j;}}static Response request(Context c,String path,JSONObject data,ConnectionHook hook)throws Exception{if(during!=null){Runnable r=during;during=null;r.run();}if(response==null)throw new java.io.IOException("offline");return response;}static class Pref{Map<String,Object> m=new HashMap<>();Pref edit(){return this;}Pref putBoolean(String k,boolean v){m.put(k,v);return this;}Pref putString(String k,String v){m.put(k,v);return this;}Pref putLong(String k,long v){m.put(k,v);return this;}Pref remove(String k){m.remove(k);return this;}boolean getBoolean(String k,boolean v){return (Boolean)m.getOrDefault(k,v);}String getString(String k,String v){return (String)m.getOrDefault(k,v);}void apply(){}boolean commit(){return true;}}}